#!/usr/bin/env bash
# Creates .env with fresh random secrets. Runs once; refuses to overwrite an existing .env. Prints no secret.
set -euo pipefail
cd "$(dirname "$0")"
if [ -f .env ]; then
  echo ".env already exists; nothing changed. Delete it first if you really want new secrets (existing databases would stop working)."
  exit 0
fi
rand() { openssl rand -hex "$1"; }
cat > .env <<ENV
# ---- Lab Tracker settings (edit these two) --------------------------------
DOMAIN=lab.example.com
COMPANY_NAME=Lab Tracker
# ---- secrets (generated by make-env.sh, keep this file private) -----------
POSTGRES_PASSWORD=$(rand 24)
REPLICATOR_PASSWORD=$(rand 24)
DASH_RO_PASSWORD=$(rand 24)
ADMIN_PASSWORD=$(openssl rand -base64 18 | tr -d '/+=')
ODOO_MASTER_PASSWORD=$(rand 24)
# ---- optional ---------------------------------------------------------------
ODOO_DB=labtracker
ODOO_BIND=127.0.0.1
ODOO_PORT=8069
ODOO_CHAT_PORT=8072
WORKERS=2
BACKUP_TIME=03:10
BACKUP_KEEP_DAYS=14
LAB_CREATE_TEST_USERS=0
ENV
chmod 600 .env
echo "Created .env with random secrets (file mode 600)."
echo "Next: edit DOMAIN and COMPANY_NAME in .env, then: docker compose --profile tls --profile backup up -d"
echo "Your admin login password is the ADMIN_PASSWORD line in .env  (show it with: grep ^ADMIN_PASSWORD .env)"
